import { Component } from '@angular/core';
import { EmpleadosService } from 'src/app/services/empleados.service';
import { NgForm } from '@angular/forms';
import { Empleado } from 'src/app/models/empleado';

@Component({
  selector: 'app-empleados',
  templateUrl: './empleados.component.html',
  styleUrls: ['./empleados.component.css']
})
export class EmpleadosComponent {
  addEmploye(form: NgForm){
    console.log(form.value);
  }
  resetForm(form?: NgForm) {
    if(form) {
      form.reset();
      this.empleadoService.empleadoSeleccionado = new Empleado;
    }
  }
  constructor (public empleadoService: EmpleadosService){}
}
<div class="container"></div>
<div class="row">
    <div class="col s5">
        <div class="card">
            <div class="card-content">
                <form #empleadoForm="ngForm" (ngSubmit)="addEmploye()"></form>
            </div>
        </div>
    </div>
    <div class="col s12">
        <input type="text" name="nombre" #nombre="ngModel" 
        [(ngModel)] = "empleadoService.empleadoSeleccionado.nombre" placeholder="introduzca su nombre">
    </div>
    <div class="col s12">
        <input type="text" name="cargo" #cargo="ngModel" 
        [(ngModel)] = "empleadoService.empleadoSeleccionado.cargo" placeholder="introduzca su cargo">
    </div>
    <div class="col s12">
        <input type="text" name="departamento" #departamento="ngModel" 
        [(ngModel)] = "empleadoService.empleadoSeleccionado.departamento" placeholder="introduzca su departamento">
    </div>
    <div class="col s12">
        <input type="number" name="salario" #salario="ngModel" 
        [(ngModel)] = "empleadoService.empleadoSeleccionado.salario" placeholder="introduzca su salario">
    </div>
    <div class="card-action">
        <div class="input-field col 12">
            <button class = "btn right" (click)="resetForm(empleadoForm)">RESET</button>
            <button class = "btn right">ENVIAR</button>
        </div>
    </div>
</div>
